import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
  } = ctx.THREE;

  const root = new Group();
  root.name = 'collection-card-2';

  const resources = [];
  const primitiveResults = [];
  const timelines = [];

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: false,
  });

  const gradientT = smoothstep(0.0, 1.0, uv().y);
  const lowerGradient = mix(
    color('#0b0b10'),
    color('#16161d'),
    gradientT
  );
  backdropMaterial.colorNode = mix(
    lowerGradient,
    color('#16161d'),
    smoothstep(0.52, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const shadowGeometry = new CircleGeometry(1.8, 64);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'contact-shadow';
  contactShadow.scale.set(1.35, 0.48, 1);
  contactShadow.position.set(0, -1.12, -0.7);
  root.add(contactShadow);

  const cardGeometry = new PlaneGeometry(4.9, 3.05);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: false,
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'collection-card-surface';
  card.position.z = -0.45;
  root.add(card);

  const imageGeometry = new PlaneGeometry(4.72, 2.87);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    depthWrite: true,
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'orb-decor-image';
  imagePlane.position.z = -0.2;
  root.add(imagePlane);

  const accentGeometry = new PlaneGeometry(0.72, 0.055);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: false,
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'signal-red-accent';
  accent.position.set(-1.98, -1.42, 0.08);
  root.add(accent);

  const edgeGeometry = new PlaneGeometry(4.9, 0.018);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.34,
  });
  const topEdge = new Mesh(edgeGeometry, edgeMaterial);
  topEdge.name = 'machined-top-edge';
  topEdge.position.set(0, 1.525, 0.08);
  root.add(topEdge);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      resources.push(loadedTexture);
      imageMaterial.colorNode = texture(loadedTexture);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || item.text.length === 0) continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.role === 'accent' ? '#ff2a38' : '#e8ecf2',
      align: item.align ?? 'left',
      maxWidthPx: item.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });
    textObject.position.set(
      item.position?.x ?? -2.1,
      item.position?.y ?? 1.82,
      item.position?.z ?? 0.12
    );
    root.add(textObject);
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;
    const result = handler(root, primitive.params ?? {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const result of primitiveResults) {
      if (result && typeof result.cleanup === 'function') result.cleanup();
    }

    const disposedMaterials = new Set();
    const disposedGeometries = new Set();

    root.traverse((object) => {
      if (object.geometry && !disposedGeometries.has(object.geometry)) {
        object.geometry.dispose();
        disposedGeometries.add(object.geometry);
      }

      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        for (const material of materials) {
          if (!disposedMaterials.has(material)) {
            material.dispose();
            disposedMaterials.add(material);
          }
        }
      }
    });

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }

    root.clear();
  };

  return root;
}
